import json,glob
for d in glob.glob('*/*/subagents/workflows/wf_*'):
    if not any(x in d for x in ('wf_e380f10f','wf_00451c77','wf_49e3312a')): continue
    st=set();rs=set();fl=set()
    for l in open(d+'/journal.jsonl'):
        try:o=json.loads(l)
        except: continue
        a=o.get('agentId')
        if o.get('type')=='started':st.add(a)
        elif o.get('type')=='result':rs.add(a)
        elif o.get('type')=='failed':fl.add(a)
    tok=0
    for f in glob.glob(d+'/agent-*.jsonl'):
        seen={}
        for l in open(f):
            try:o=json.loads(l)
            except: continue
            u=(o.get('message') or {}).get('usage') if isinstance(o.get('message'),dict) else None
            if u and o.get('type')=='assistant':
                seen[o.get('requestId') or o.get('uuid')]=u
        for u in seen.values():
            tok+=u.get('input_tokens',0)+u.get('output_tokens',0)+u.get('cache_creation_input_tokens',0)
    print(d.split('/')[-1],len(st),len(rs),len(fl-rs),'tok~',tok)
